INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v5-sun-earths', 'Представь, что Земли выкладывают в ряд вплотную, как бусины, прямо поперёк Солнца — от края до края через центр. Сколько Земель понадобится?', 'Сколько Земель в ряд уложатся поперёк Солнца?', 'Земель', 109.2, 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/sunfact.html', '2026-11-12', '2026-11-19', '{"steps":[{"label":"Средний радиус Солнца","value":695700,"unit":"км","sourceUrl":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/sunfact.html","sourceTitle":"NASA — Sun Fact Sheet"},{"label":"Средний радиус Земли","value":6371,"unit":"км","sourceUrl":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html","sourceTitle":"NASA — Earth Fact Sheet"}],"summary":"695 700 ÷ 6371 ≈ 109,2 Земли. А по объёму в Солнце влезло бы около 1,3 млн Земель."}', 1794445298393);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v5-kz-fields', 'Сколько футбольных полей 105 × 68 м поместится по площади на территории Казахстана? Горы, озёра и города не мешают — считаем только площадь.', 'Сколько футбольных полей поместится в Казахстане?', 'полей', 381638936, 'https://ru.wikipedia.org/wiki/%D0%9A%D0%B0%D0%B7%D0%B0%D1%85%D1%81%D1%82%D0%B0%D0%BD', '2026-11-12', '2026-11-20', '{"steps":[{"label":"Площадь Казахстана","value":2724902,"unit":"км²","sourceUrl":"https://ru.wikipedia.org/wiki/%D0%9A%D0%B0%D0%B7%D0%B0%D1%85%D1%81%D1%82%D0%B0%D0%BD","sourceTitle":"Википедия — Казахстан"},{"label":"Площадь поля по условию","value":7140,"unit":"м²","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — перевод единиц"}],"summary":"2 724 902 км² = 2,72 трлн м²; ÷ 7140 ≈ 381,6 млн полей. Это примерно по 19 полей на каждого жителя страны."}', 1794445298393);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v5-count-billion', 'Сколько лет уйдёт, чтобы досчитать до миллиарда, если называть одно число в секунду — без сна, еды и выходных?', 'Сколько лет считать до миллиарда?', 'лет', 31.7, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-12', '2026-11-21', '{"steps":[{"label":"Чисел по условию","value":1000000000,"unit":"","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Условие задачи"},{"label":"Секунд в году (365,25 суток)","value":31557600,"unit":"с","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — day = 86 400 s"}],"summary":"1 000 000 000 ÷ 31 557 600 ≈ 31,7 года. На деле дольше: «семьсот сорок три миллиона…» за секунду не выговорить."}', 1794445298393);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v5-marathon-laps', 'Сколько кругов по беговой дорожке стадиона длиной 400 м нужно пробежать, чтобы набрать полную марафонскую дистанцию?', 'Сколько кругов стадиона в одном марафоне?', 'кругов', 105.5, 'https://worldathletics.org/about-iaaf/documents/book-of-rules', '2026-11-12', '2026-11-22', '{"steps":[{"label":"Марафонская дистанция","value":42195,"unit":"м","sourceUrl":"https://worldathletics.org/about-iaaf/documents/book-of-rules","sourceTitle":"World Athletics — правила соревнований"},{"label":"Круг стадиона по первой дорожке","value":400,"unit":"м","sourceUrl":"https://worldathletics.org/about-iaaf/documents/book-of-rules","sourceTitle":"World Athletics — правила соревнований"}],"summary":"42 195 ÷ 400 ≈ 105,5 круга. Лишние 195 м — наследие Олимпиады 1908 года: финиш поставили напротив королевской ложи."}', 1794445298393);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v5-walk-moon', 'Если бы до Луны вела дорога, сколько дней пришлось бы идти по ней со скоростью 5 км/ч — без остановок на сон и еду? Расстояние бери среднее.', 'Сколько дней идти пешком до Луны?', 'дней', 3203, 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/moonfact.html', '2026-11-12', '2026-11-23', '{"steps":[{"label":"Среднее расстояние до Луны","value":384400,"unit":"км","sourceUrl":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/moonfact.html","sourceTitle":"NASA — Moon Fact Sheet"},{"label":"Скорость пешехода по условию","value":5,"unit":"км/ч","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Условие задачи"}],"summary":"384 400 ÷ 5 = 76 880 часов ≈ 3203 суток — почти 9 лет непрерывной ходьбы. Свет проходит этот путь за 1,3 секунды."}', 1794445298393);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v5-baiterek-everest', 'Сколько монументов «Байтерек» высотой 105 м нужно поставить друг на друга, чтобы стопка от уровня моря сравнялась с вершиной Эвереста?', 'Сколько Байтереков в стопке достанут до вершины Эвереста?', 'Байтереков', 84.3, 'https://govt.chinadaily.com.cn/s/202012/09/WS5fd09fc4498eaba5051bd741/qomolangma-remeasured-at-8-848-86-m.html', '2026-11-12', '2026-11-24', '{"steps":[{"label":"Высота Эвереста (обмер Китая и Непала, 2020)","value":8848.86,"unit":"м","sourceUrl":"https://govt.chinadaily.com.cn/s/202012/09/WS5fd09fc4498eaba5051bd741/qomolangma-remeasured-at-8-848-86-m.html","sourceTitle":"China Daily — Qomolangma remeasured at 8,848.86 m"},{"label":"Высота «Байтерека» с шаром","value":105,"unit":"м","sourceUrl":"https://www.inform.kz/ru/chto-my-znaem-o-monumente-astana-bayterek_a3277443","sourceTitle":"Казинформ — что мы знаем о монументе «Астана-Байтерек»"}],"summary":"8848,86 ÷ 105 ≈ 84,3 Байтерека. Шар верхнего оказался бы там, где воздух втрое реже, чем у земли."}', 1794445298393);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v5-billion-tenge', 'Тебе дали миллиард тенге с одним условием: тратить ровно 100 000 тенге в день, каждый день. На сколько лет хватит денег? Проценты по вкладу не считаем.', 'Сколько лет тратить миллиард тенге по 100 тысяч в день?', 'лет', 27.4, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-12', '2026-11-25', '{"steps":[{"label":"Дней до конца денег","value":10000,"unit":"дней","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Расчёт по условию"},{"label":"Суток в году","value":365.25,"unit":"сут","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — year (365.25 d)"}],"summary":"1 000 000 000 ÷ 100 000 = 10 000 дней ≈ 27,4 года. Миллион при таком темпе кончился бы за 10 дней."}', 1794445298393);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v5-lightning-day', 'Сколько вспышек молний происходит на всей Земле за одни сутки? Считай в среднем за год, вместе с молниями внутри облаков.', 'Сколько молний сверкает на Земле за сутки?', 'вспышек', 3801600, 'https://www.earthdata.nasa.gov/topics/atmosphere/lightning', '2026-11-12', '2026-11-26', '{"steps":[{"label":"Средняя частота вспышек по спутникам NASA","value":44,"unit":"в секунду","sourceUrl":"https://www.earthdata.nasa.gov/topics/atmosphere/lightning","sourceTitle":"NASA Earthdata — Lightning: от 35 до 55 в секунду по сезонам"},{"label":"Секунд в сутках","value":86400,"unit":"с","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — day = 86 400 s"}],"summary":"44 × 86 400 ≈ 3,8 млн вспышек в сутки. Летом в Северном полушарии их больше, зимой — около 3 млн."}', 1794445298393);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v5-germanies-kz', 'Во сколько раз Казахстан больше Германии по площади? Иначе: сколько Германий поместится на его территории?', 'Сколько Германий поместится в Казахстане?', 'Германий', 7.6, 'https://ru.wikipedia.org/wiki/%D0%9A%D0%B0%D0%B7%D0%B0%D1%85%D1%81%D1%82%D0%B0%D0%BD', '2026-11-12', '2026-11-27', '{"steps":[{"label":"Площадь Казахстана","value":2724902,"unit":"км²","sourceUrl":"https://ru.wikipedia.org/wiki/%D0%9A%D0%B0%D0%B7%D0%B0%D1%85%D1%81%D1%82%D0%B0%D0%BD","sourceTitle":"Википедия — Казахстан"},{"label":"Площадь Германии","value":357592,"unit":"км²","sourceUrl":"https://ru.wikipedia.org/wiki/%D0%93%D0%B5%D1%80%D0%BC%D0%B0%D0%BD%D0%B8%D1%8F","sourceTitle":"Википедия — Германия"}],"summary":"2 724 902 ÷ 357 592 ≈ 7,6 Германии. Людей при этом в Германии в четыре с лишним раза больше."}', 1794445298393);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v5-chess-grains', 'По легенде, изобретатель шахмат попросил у правителя награду: одно зерно на первую клетку доски, два — на вторую, четыре — на третью и так далее, удваивая. Сколько зёрен ляжет на последнюю, 64-ю клетку? Можно отвечать в виде 5e12.', 'Сколько зёрен окажется на последней клетке шахматной доски?', 'зёрен', 9223372036854776000, 'https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%B4%D0%B0%D1%87%D0%B0_%D0%BE_%D0%B7%D1%91%D1%80%D0%BD%D0%B0%D1%85_%D0%BD%D0%B0_%D1%88%D0%B0%D1%85%D0%BC%D0%B0%D1%82%D0%BD%D0%BE%D0%B9_%D0%B4%D0%BE%D1%81%D0%BA%D0%B5', '2026-11-12', '2026-11-28', '{"steps":[{"label":"Удвоений от первой клетки до 64-й","value":63,"unit":"","sourceUrl":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%B4%D0%B0%D1%87%D0%B0_%D0%BE_%D0%B7%D1%91%D1%80%D0%BD%D0%B0%D1%85_%D0%BD%D0%B0_%D1%88%D0%B0%D1%85%D0%BC%D0%B0%D1%82%D0%BD%D0%BE%D0%B9_%D0%B4%D0%BE%D1%81%D0%BA%D0%B5","sourceTitle":"Википедия — задача о зёрнах на шахматной доске"}],"summary":"2⁶³ ≈ 9,2 квинтиллиона зёрен — сотни миллиардов тонн, в сотни раз больше годового урожая риса всей планеты."}', 1794445298393);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v5-eiffel-phones', 'Металлический каркас Эйфелевой башни весит 7300 тонн. Сколько смартфонов массой 170 г нужно, чтобы уравновесить его на гигантских весах?', 'Сколько смартфонов весят как Эйфелева башня?', 'смартфонов', 42941176, 'https://www.toureiffel.paris/en/news/history-and-culture/15-essential-things-to-know-about-eiffel-tower', '2026-11-12', '2026-11-29', '{"steps":[{"label":"Масса металлического каркаса башни","value":7300,"unit":"т","sourceUrl":"https://www.toureiffel.paris/en/news/history-and-culture/15-essential-things-to-know-about-eiffel-tower","sourceTitle":"Официальный сайт Эйфелевой башни"},{"label":"Масса смартфона по условию","value":0.17,"unit":"кг","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Условие задачи"}],"summary":"7 300 000 кг ÷ 0,17 ≈ 42,9 млн смартфонов. А если переплавить весь её металл в плиту размером с основание башни, плита вышла бы толщиной всего около 6 см."}', 1794445298393);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v5-moons-earth', 'Если бы Землю можно было наполнить, как мешок, сколько Лун поместилось бы внутри по объёму?', 'Сколько Лун поместится внутри Земли?', 'Лун', 49.3, 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html', '2026-11-12', '2026-11-30', '{"steps":[{"label":"Объём Земли","value":1083210000000,"unit":"км³","sourceUrl":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html","sourceTitle":"NASA — Earth Fact Sheet"},{"label":"Объём Луны","value":21968000000,"unit":"км³","sourceUrl":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/moonfact.html","sourceTitle":"NASA — Moon Fact Sheet"}],"summary":"108,321 ÷ 2,1968 ≈ 49,3 Луны. А по массе Земля тяжелее Луны в 81 раз: Луна заметно «рыхлее»."}', 1794445298393);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v5-heartbeats', 'Сколько раз ударит сердце за 80 лет жизни, если оно бьётся ровно 70 раз в минуту — днём и ночью, без перерывов?', 'Сколько раз сердце ударит за 80 лет?', 'ударов', 2945376000, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-12', '2026-12-01', '{"steps":[{"label":"Ударов в сутки при 70 в минуту","value":100800,"unit":"","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Расчёт по условию"},{"label":"Суток за 80 лет","value":29220,"unit":"сут","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — year (365.25 d)"}],"summary":"100 800 × 29 220 ≈ 2,95 млрд ударов. Каждые сутки сердце перекачивает несколько тонн крови."}', 1794445298393);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v5-sunlight-minutes', 'Сколько минут летит свет от Солнца до Земли? То есть насколько «старое» Солнце мы видим, когда смотрим на небо.', 'Сколько минут летит до нас солнечный свет?', 'минут', 8.32, 'https://www.iau.org/static/resolutions/IAU2012_English.pdf', '2026-11-12', '2026-12-02', '{"steps":[{"label":"Астрономическая единица","value":149597870.7,"unit":"км","sourceUrl":"https://www.iau.org/static/resolutions/IAU2012_English.pdf","sourceTitle":"МАС — резолюция B2 (2012)"},{"label":"Скорость света","value":299792.458,"unit":"км/с","sourceUrl":"https://physics.nist.gov/cgi-bin/cuu/Value?c","sourceTitle":"NIST — speed of light in vacuum"}],"summary":"149 597 870,7 ÷ 299 792,458 ≈ 499 с ≈ 8,3 минуты. Погасни Солнце — мы бы узнали об этом только через 8 минут."}', 1794445298393);
